<script lang="ts" generics="NodeType extends Node = Node, EdgeType extends Edge = Edge">import {
  ConnectionLineType,
  getBezierPath,
  getConnectionStatus,
  getSmoothStepPath,
  getStraightPath
} from "@xyflow/system";
let {
  store = $bindable(),
  type,
  containerStyle,
  style,
  LineComponent
} = $props();
let path = $derived.by(() => {
  if (!store.connection.inProgress) {
    return "";
  }
  const pathParams = {
    sourceX: store.connection.from.x,
    sourceY: store.connection.from.y,
    sourcePosition: store.connection.fromPosition,
    targetX: store.connection.to.x,
    targetY: store.connection.to.y,
    targetPosition: store.connection.toPosition
  };
  switch (type) {
    case ConnectionLineType.Bezier: {
      const [path2] = getBezierPath(pathParams);
      return path2;
    }
    case ConnectionLineType.Straight: {
      const [path2] = getStraightPath(pathParams);
      return path2;
    }
    case ConnectionLineType.Step:
    case ConnectionLineType.SmoothStep: {
      const [path2] = getSmoothStepPath({
        ...pathParams,
        borderRadius: type === ConnectionLineType.Step ? 0 : void 0
      });
      return path2;
    }
  }
});
</script>

{#if store.connection.inProgress}
  <svg
    width={store.width}
    height={store.height}
    class="svelte-flow__connectionline"
    style={containerStyle}
  >
    <g class={['svelte-flow__connection', getConnectionStatus(store.connection.isValid)]}>
      {#if LineComponent}
        <LineComponent></LineComponent>
      {:else}
        <path d={path} {style} fill="none" class="svelte-flow__connection-path" />
      {/if}
    </g>
  </svg>
{/if}
