<script lang="ts">let {
  id,
  x,
  y,
  width,
  height,
  borderRadius = 5,
  color,
  shapeRendering,
  strokeColor,
  strokeWidth = 2,
  selected,
  class: className,
  nodeComponent
} = $props();
</script>

{#if nodeComponent}
  {@const CustomComponent = nodeComponent}

  <CustomComponent
    {id}
    {x}
    {y}
    {width}
    {height}
    {borderRadius}
    class={className}
    {color}
    {shapeRendering}
    {strokeColor}
    {strokeWidth}
    {selected}
  />
{:else}
  <rect
    class={['svelte-flow__minimap-node', className]}
    class:selected
    {x}
    {y}
    rx={borderRadius}
    ry={borderRadius}
    {width}
    {height}
    style:fill={color}
    style:stroke={strokeColor}
    style:stroke-width={strokeWidth}
    shape-rendering={shapeRendering}
  />
{/if}
