<script lang="ts">import { Position, getNodeToolbarTransform } from "@xyflow/system";
import { useStore } from "../../store";
import { getNodeIdContext } from "../../store/context";
import { hideOnSSR, portal } from "../../actions/portal";
import { useSvelteFlow } from "../../hooks/useSvelteFlow.svelte";
let {
  nodeId,
  position = Position.Top,
  align = "center",
  offset = 10,
  isVisible,
  children,
  ...rest
} = $props();
const store = useStore();
const { getNodesBounds } = useSvelteFlow();
const contextNodeId = getNodeIdContext();
let toolbarNodes = $derived.by(() => {
  store.nodes;
  const nodeIds = Array.isArray(nodeId) ? nodeId : [nodeId ?? contextNodeId];
  return nodeIds.reduce((res, nodeId2) => {
    if (!nodeId2) {
      throw new Error("Either pass a nodeId or use within a Custom Node component");
    }
    const node = store.nodeLookup.get(nodeId2);
    if (node) {
      res.push(node);
    }
    return res;
  }, []);
});
let transform = $derived.by(() => {
  const nodeRect = getNodesBounds(toolbarNodes);
  if (nodeRect) {
    return getNodeToolbarTransform(nodeRect, store.viewport, position, offset, align);
  }
  return "";
});
let zIndex = $derived(
  toolbarNodes.length === 0 ? 1 : Math.max(...toolbarNodes.map((node) => (node.internals.z || 5) + 1))
);
let selectedNodesCount = $derived(store.nodes.filter((node) => node.selected).length);
let isActive = $derived(
  typeof isVisible === "boolean" ? isVisible : toolbarNodes.length === 1 && toolbarNodes[0].selected && selectedNodesCount === 1
);
</script>

{#if store.domNode && isActive && toolbarNodes}
  <div
    use:portal={'root'}
    style:display={hideOnSSR().value ? 'none' : undefined}
    class="svelte-flow__node-toolbar"
    data-id={toolbarNodes.reduce((acc, node) => `${acc}${node.id} `, '').trim()}
    style:position="absolute"
    style:transform
    style:z-index={zIndex}
    {...rest}
  >
    {@render children?.()}
  </div>
{/if}
