<script lang="ts">import { useStore } from "../../store";
import { getEdgeIdContext } from "../../store/context";
import { XYHandle } from "@xyflow/system";
import { EdgeLabel } from "../EdgeLabel";
let {
  type,
  reconnecting = $bindable(false),
  position,
  class: className,
  size = 25,
  dragThreshold = 1,
  children,
  ...rest
} = $props();
const store = useStore();
const edgeId = getEdgeIdContext(
  "EdgeReconnectAnchor must be used within a Custom Edge component"
);
const onPointerDown = (event) => {
  if (event.button !== 0) {
    return;
  }
  const {
    autoPanOnConnect,
    domNode,
    isValidConnection,
    connectionMode,
    connectionRadius,
    onconnectstart,
    onconnectend,
    onreconnect,
    onreconnectstart,
    onreconnectend,
    onbeforereconnect,
    cancelConnection,
    nodeLookup,
    flowId,
    panBy,
    updateConnection,
    edgeLookup
  } = store;
  let edge = edgeLookup.get(edgeId);
  const _onConnectStart = (evt, params) => {
    reconnecting = true;
    onreconnectstart?.(event, edge, type);
    onconnectstart?.(evt, params);
  };
  const opposite = type === "target" ? { nodeId: edge.source, handleId: edge.sourceHandle ?? null, type: "source" } : {
    nodeId: edge.target,
    handleId: edge.targetHandle ?? null,
    type: "target"
  };
  XYHandle.onPointerDown(event, {
    autoPanOnConnect,
    connectionMode,
    connectionRadius,
    domNode,
    handleId: opposite.handleId,
    nodeId: opposite.nodeId,
    nodeLookup,
    isTarget: opposite.type === "target",
    edgeUpdaterType: opposite.type,
    lib: "svelte",
    flowId,
    cancelConnection,
    panBy,
    isValidConnection,
    onConnectStart: _onConnectStart,
    onConnectEnd: onconnectend,
    onConnect: (connection) => {
      const reconnectedEdge = { ...edge, ...connection };
      const newEdge = onbeforereconnect ? onbeforereconnect(reconnectedEdge, edge) : reconnectedEdge;
      if (!newEdge) {
        return;
      }
      store.edges = store.edges.map((e) => e.id === edge.id ? newEdge : e);
      onreconnect?.(edge, connection);
    },
    onReconnectEnd: (event2, connectionState) => {
      reconnecting = false;
      onreconnectend?.(event2, edge, opposite.type, connectionState);
    },
    updateConnection,
    getTransform: () => [store.viewport.x, store.viewport.y, store.viewport.zoom],
    getFromHandle: () => store.connection.fromHandle,
    dragThreshold: dragThreshold ?? store.connectionDragThreshold,
    handleDomNode: event.currentTarget
  });
};
</script>

<EdgeLabel
  x={position?.x}
  y={position?.y}
  width={size}
  height={size}
  class={[
    'svelte-flow__edgeupdater',
    `svelte-flow__edgeupdater-${type}`,
    store.noPanClass,
    className
  ]}
  onpointerdown={onPointerDown}
  transparent
  {...rest}
>
  {#if !reconnecting && children}
    {@render children()}
  {/if}
</EdgeLabel>
