<script lang="ts" generics="NodeType extends Node = Node, EdgeType extends Edge = Edge">import { onDestroy, setContext } from "svelte";
import { createStore, key } from "../../store";
let { children } = $props();
let store = $state.raw(
  createStore({
    props: {},
    nodes: [],
    edges: []
  })
);
setContext(key, {
  provider: true,
  getStore() {
    return store;
  },
  setStore: (newStore) => {
    store = newStore;
  }
});
onDestroy(() => {
  store.reset();
});
</script>

{@render children?.()}
